/* From Uiverse.io by neerajbaniwal  - Tags: radio, submit, switcher, html, css, 3d button */
.__UIV_SCOPE__ .radiogroup {
  padding: 48px 64px;
  border-radius: 16px;
  background: #ecf0f3;
  box-shadow: 4px 4px 4px 0px #d1d9e6 inset, -4px -4px 4px 0px #ffffff inset;
}

.__UIV_SCOPE__ .wrapper {
  margin: 8px 0;
}

.__UIV_SCOPE__ .state {
  position: absolute;
  top: 0;
  right: 0;
  opacity: 1e-5;
  pointer-events: none;
}

.__UIV_SCOPE__ .label {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  color: #394a56;
}

.__UIV_SCOPE__ .text {
  margin-left: 16px;
  opacity: 0.6;
  transition: opacity 0.2s linear, transform 0.2s ease-out;
}

.__UIV_SCOPE__ .indicator {
  position: relative;
  border-radius: 50%;
  height: 30px;
  width: 30px;
  box-shadow: -8px -4px 8px 0px #ffffff, 8px 4px 12px 0px #d1d9e6;
  overflow: hidden;
}

.__UIV_SCOPE__ .indicator::before,
.__UIV_SCOPE__ .indicator::after {
  content: "";
  position: absolute;
  top: 10%;
  left: 10%;
  height: 80%;
  width: 80%;
  border-radius: 50%;
}

.__UIV_SCOPE__ .indicator::before {
  box-shadow: -4px -2px 4px 0px #d1d9e6, 4px 2px 8px 0px #fff;
}

.__UIV_SCOPE__ .indicator::after {
  background-color: #ecf0f3;
  box-shadow: -4px -2px 4px 0px #fff, 4px 2px 8px 0px #d1d9e6;
  transform: scale3d(1, 1, 1);
  transition: opacity 0.25s ease-in-out, transform 0.25s ease-in-out;
}

.__UIV_SCOPE__ .state:checked ~ .label .indicator::after {
  transform: scale3d(0.975, 0.975, 1) translate3d(0, 10%, 0);
  opacity: 0;
}

.__UIV_SCOPE__ .state:focus ~ .label .text {
  transform: translate3d(8px, 0, 0);
  opacity: 1;
}

.__UIV_SCOPE__ .label:hover .text {
  opacity: 1;
}
